input.sparql:
SELECT ?lightingPower ?buildingPower 
FROM <http://Brick#> 
WHERE {
  ?lightingPower brick:isMeasuring ?z ;
                 rdf:type brick:Lighting_Power_Sensor.

  ?buildingPower brick:isMeasuring [ rdf:type brick:Electric_Power_Meter ];
                 rdf:type brick:Electric_Power_Sensor.
}
